void Rec(const std::filesystem::path&p,const std::string&id,std::uint8_t poison,const std::vector<std::uint8_t>&w0,const std::vector<std::uint8_t>&b0,const std::array<std::vector<std::uint8_t>,6>&i0,const std::vector<std::uint8_t>&w1,const std::vector<std::uint8_t>&b1,const std::array<std::vector<std::uint8_t>,6>&i1,const std::vector<std::uint8_t>&out,std::size_t mm,std::size_t cc,const std::string&dev){std::ofstream s(p);bool pass=mm==0&&cc==0;s<<"{\n  \"schema\": \"neuralstudio.fg.custom-block1-bot1-run.v1\",\n  \"backend\": \"mac-metal\",\n  \"run_id\": \""<<id<<"\",\n  \"process_id\": "<<getpid()<<",\n  \"poison_byte\": "<<unsigned(poison)<<",\n  \"trace_launch_token\": \"launch-000083\",\n  \"module_token\": 66,\n  \"module_bytes\": "<<c::kModuleBytes<<",\n  \"module_sha256\": \""<<c::kModuleSha256<<"\",\n  \"metal_function\": \"fg_custom_block1_bot1\",\n  \"selected_rtx_grid\": [40, 46, 3],\n  \"selected_rtx_block\": [32, 8, 1],\n  \"metal_dispatch_threads\": [640, 368, 8],\n  \"metal_threads_per_threadgroup\": [8, 4, 1],\n  \"weight_source_token\": 202,\n  \"bias_source_token\": 204,\n  \"model_manifest_sha256\": \""<<c::kManifestSha256<<"\",\n  \"weight_pre_sha256\": \""<<Sha256(w0)<<"\",\n  \"weight_post_sha256\": \""<<Sha256(w1)<<"\",\n  \"bias_pre_sha256\": \""<<Sha256(b0)<<"\",\n  \"bias_post_sha256\": \""<<Sha256(b1)<<"\",\n  \"input_generator\": \"splitmix64-fg-custom-block1-bot1-v1\",\n  \"input_pre_sha256\": [\""<<Sha256(i0[0])<<"\", \""<<Sha256(i0[1])<<"\", \""<<Sha256(i0[2])<<"\", \""<<Sha256(i0[3])<<"\", \""<<Sha256(i0[4])<<"\", \""<<Sha256(i0[5])<<"\"],\n  \"input_post_sha256\": [\""<<Sha256(i1[0])<<"\", \""<<Sha256(i1[1])<<"\", \""<<Sha256(i1[2])<<"\", \""<<Sha256(i1[3])<<"\", \""<<Sha256(i1[4])<<"\", \""<<Sha256(i1[5])<<"\"],\n  \"output_sha256\": \""<<Sha256(out)<<"\",\n  \"output_bytes\": "<<out.size()<<",\n  \"input_mismatched_bytes\": "<<mm<<",\n  \"canary_mismatched_bytes\": "<<cc<<",\n  \"external_model_files_opened\": true,\n  \"expected