d commit];[cmd waitUntilCompleted];if(cmd.status==MTLCommandBufferStatusError)throw std::runtime_error(cmd.error.localizedDescription.UTF8String);auto w1=Payload(w,c::kWeightBytes),b1=Payload(b,c::kBiasBytes);std::array<std::vector<std::uint8_t>,6>i1={Payload(l0,c::kLatentBytes),Payload(l1,c::kLatentBytes),Payload(l2,c::kLatentBytes),Payload(s0,c::kSkip0Bytes),Payload(s1,c::kSkip1Bytes),Payload(s2,c::kSkip2Bytes)};auto o=Payload(out,c::kOutputBytes);std::size_t mm=Mismatches(w0,w1)+Mismatches(b0,b1);for(int j=0;j<6;++j)mm+=Mismatches(i0[j],i1[j]);auto can=CanaryMismatches(w,c::kWeightBytes)+CanaryMismatches(b,c::kBiasBytes)+CanaryMismatches(l0,c::kLatentBytes)+CanaryMismatches(l1,c::kLatentBytes)+CanaryMismatches(l2,c::kLatentBytes)+CanaryMismatches(s0,c::kSkip0Bytes)+CanaryMismatches(s1,c::kSkip1Bytes)+CanaryMismatches(s2,c::kSkip2Bytes)+CanaryMismatches(out,c::kOutputBytes);Rec(dir/"run-receipt.json",v[5],poison,w0,b0,i0,w1,b1,i1,o,mm,can,d.name.UTF8String);Write(dir/"output.bin",o);bool pass=mm==0&&can==0;std::cout<<"output_sha256="<<Sha256(o)<<"\nresult="<<(pass?"pass":"fail")<<'\n';return pass?0:3;}catch(const std::exception&e){std::cerr<<"error="<<e.what()<<'\n';return 1;}}}
